'use client';

// The AI sparkle beside the name of whoever an agent wrote for (liveplanner's items.md "History": a card's Activity
// run; liveknowledge's verification.md "Made by a person or an agent" and version-history.md "In the editor"): a quiet
// violet disc with the sparkle, its words ("Edited by AI") its accessible name and its tooltip. Never "Generated by
// AI", which is a comment's alone (CommentMarks.tsx).
import type { HTMLAttributes } from 'react';
import { lucideGlyph, Tooltip } from '@liveworkspace/ui';
import { lucideSparkles } from '@liveworkspace/icons/lucide';

const SparkleIcon = lucideGlyph(lucideSparkles, 10);

type MarkProps = { words: string } & Omit<
  HTMLAttributes<HTMLSpanElement>,
  'children' | 'role' | 'aria-label' | 'className'
>;

/** The sparkle, named by `words`; any `data-*` given rides on it. */
export function AiWriterMark({ words, ...rest }: MarkProps) {
  return (
    <Tooltip label={words}>
      <span
        data-ai-writer=""
        {...rest}
        role="img"
        aria-label={words}
        className="inline-flex size-4 shrink-0 items-center justify-center rounded-full bg-violet-50 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300"
      >
        <SparkleIcon aria-hidden />
      </span>
    </Tooltip>
  );
}
